const request = JSON.parse(await Deno.readTextFile(Deno.args[0]));
const operation = request.NETSCRIPT_PRISMA_OPERATION;
if (typeof operation !== 'string' || !/^[a-z-]+$/.test(operation)) {
  throw new Error('Invalid NetScript database operation request.');
}
