// IMPL-EVAL scratch: render db-cli-mode + register-infrastructure emission from a given tree.
const tree = Deno.args[0];
const out = Deno.args[1];

const dbCli = await import(
  `file://${tree}/packages/cli/src/kernel/templates/aspire/helpers/generate-db-cli-mode.ts`
);
const regInfra = await import(
  `file://${tree}/packages/cli/src/kernel/templates/aspire/helpers/register/generate-register-infrastructure.ts`
);

const MINIMAL_DATABASE = {
  Enabled: true,
  Engine: "Postgres",
  Mode: "Container",
  Persistent: false,
};
const DATABASE_EXTERNAL = {
  Enabled: true,
  Engine: "Postgres",
  Mode: "External",
  Persistent: false,
};

const cliOut = dbCli.generateDbCliMode({ databases: { main: MINIMAL_DATABASE } });
const infraOut = regInfra.generateRegisterInfrastructure({
  databases: { main: MINIMAL_DATABASE, ext: DATABASE_EXTERNAL },
  caches: {},
  primaryDatabase: "main",
});

await Deno.writeTextFile(
  `${out}/db-cli-mode.mts.txt`,
  cliOut,
);
await Deno.writeTextFile(`${out}/register-infrastructure.mts.txt`, infraOut);
console.log("ok");

